  remakeNotes?: string | null;
  /** Authored case note saved to the general case-notes timeline. */
  notes?: string | null;
  /** Prescription notes saved as one dated Rx history entry. */
  rxNotes?: string | null;
  shade?: string | null;
  /** Gingival / tissue shade, primarily used for Removable cases (e.g. "Light Pink", "Medium Pink"). Omit or send null for non-Removable cases. */
  gingivialShade?: string | null;
