export type DoctorDuplicateClusterKind = typeof DoctorDuplicateClusterKind[keyof typeof DoctorDuplicateClusterKind];


export const DoctorDuplicateClusterKind = {
  name: 'name',
  account: 'account',
} as const;

export interface DoctorDuplicateCluster {
  labOrganizationId?: string;
  labName?: string | null;
  /** Highest pairwise similarity within the cluster (0..1). */
  topScore?: number;
  /** Stable key for this cluster, used for dismiss/restore. */
  clusterKey?: string;
  doctors?: DoctorDuplicateEntry[];
  /**
     * `name` — duplicate doctor names found on cases (the original scan).
     * `account` — duplicate provider accounts for one person, which may
     * have no cases at all.
     */
  kind?: DoctorDuplicateClusterKind;
  /**
     * Why an account cluster was not consolidated automatically
     * (conflicting emails or phone numbers). Null when there is no
     * conflict.
     */
  conflictReason?: string | null;
  /**
     * For `account` clusters: the one account number that survives
     * consolidating this whole cluster (the oldest across every member,
     * the same survivor the consolidation endpoint picks). Every other
     * account in the cluster is retired onto it, so a UI beside the
     * consolidate action must call only this one "kept". Null for `name`
     * clusters — merging names retires no account, each doctor keeps the
     * account they already have — and null when no member has a number.
     */
  survivingAccountNumber?: string | null;
}

