export interface UpdateCaseInput {
  status?: UpdateCaseInputStatus;
  priority?: UpdateCaseInputPriority;
  /** Lab station where the case is physically located. Null clears the stored station without changing the case status. */
  labLocationId?: string | null;
  /**
     * Calendar date the case was received. Updating this field also updates the Issued date of every invoice linked to the case.
     * @pattern ^\d{4}-\d{2}-\d{2}$
     */
  receivedAt?: string;
  dueDate?: string | null;
  /**
     * Optional literal wall-clock time of day for the due date, in HH:MM format. Null clears it.
     * @pattern ^([01]\d|2[0-3]):[0-5]\d$
     */
  dueTime?: string | null;
  doctorName?: string;
  patientFirstName?: string;
  patientLastName?: string;
  /**
     * Re-assign the case to a different provider organization.
     * Must be an active provider org that belongs to the same lab
     * as the case (validated server-side).
     */
  providerOrganizationId?: string;
  /**
     * When `true`, clears the AI-generated `suggestedDoctorName` and
     * `suggestedProviderOrgId` fields without affecting any other
     * case fields. Used by the "Keep as-is" action in the desktop
     * review banner.
     */
  clearSuggestion?: boolean;
  /**
     * Comma-separated bridge-connector tooth-pair string controlling
     * which adjacent restorations form a bridge span. An empty string
     * clears all connectors on the case.
     */
  bridgeConnectors?: string;
  /** Expected delivery date; `null` clears it. */
  expectedDeliveryDate?: string | null;
  /**
     * Physical tray (pan) barcode assigned to this case. An empty
     * string or omitted value leaves the existing barcode unchanged.
     * Trimmed server-side.
     */
  casePanBarcode?: string;
  /**
     * New case number. Admin/owner members only. Must be non-empty and
     * unique across all cases. Returns 409 if already in use.
     */
  caseNumber?: string;
  /** Freeform Rx/case notes visible to the lab. */
  rxNotes?: string | null;
  /** Gingival / tissue shade for Removable cases (e.g. "Light Pink"). Null clears it. Ignored for non-Removable cases. */
  gingivialShade?: string | null;
  /** Controlled remake-reason key (replaces free-text remakeReason). When set to `other`, remakeReason must contain the trimmed custom explanation. */
  remakeReasonKey?: UpdateCaseInputRemakeReasonKey;
  /**
     * Human-readable remake reason text (legacy / display fallback).
     * @maxLength 2000
     */
  remakeReason?: string;
  /** Whether this remake is charged to the provider. */
  remakeCharged?: boolean | null;
  /** Direction of shade correction needed. */
  remakeShadeLightness?: UpdateCaseInputRemakeShadeLightness;
  /** Shade that was originally prescribed. */
  remakeShadePrescribed?: string | null;
  /** Shade that was actually delivered (caused the remake). */
  remakeShadeProvided?: string | null;
  /** Material that was originally prescribed. */
  remakeMaterialPrescribed?: string | null;
  /** Material that was actually delivered (caused the remake). */
  remakeMaterialProvided?: string | null;
  /** Whether the original case was physically returned to the lab. */
  remakeReturnedToLab?: boolean | null;
  /**
     * High-level category for the remake. Auto-inferred server-side
     * from `remakeReasonKey` when omitted.
     */
  remakeCategory?: UpdateCaseInputRemakeCategory;
}

