/**
 * Invoice, statement, payment, credit, or credit-application ledger event. One payment received from a practice is a single event even when it settled several invoices: it carries the full amount received on its payment date and identifies itself by method, receipt reference, and applied statement rather than borrowing the number, doctor, and patient of one invoice. A payment recorded directly against a single invoice keeps that invoice's details.
 */
export interface StatementChargeRow {
  /** Stable event key, unique across the whole ledger. */
  id?: string;
  date?: string;
  /** invoice, statement, payment, credit_application, or customer_credit. */
  type?: string;
  rowType?: string;
  /** Reader-facing label, e.g. "Payment (3 invoices)". */
  typeLabel?: string;
  invoiceNumber?: string | null;
  /** Invoices settled by a payment event. */
  invoiceCount?: number | null;
  doctorIdentity?: string | null;
  doctorName?: string | null;
  patientName?: string | null;
  invoiceAmount?: string | null;
  paymentAmount?: string | null;
  paymentMethod?: string | null;
  /** Receipt number of the payment, or the payment's own reference. */
  referenceNumber?: string | null;
  statementId?: string | null;
  /** Period of the related statement, formatted MM-YYYY. */
  statementLabel?: string | null;
  paymentSessionId?: string | null;
  creditApplicationId?: string | null;
  openBalance?: string;
  balance?: string;
  [key: string]: unknown;
 }

